function findMin(nums) {
  let lo = 0, hi = nums.length - 1;
  if (nums[lo] <= nums[hi]) return nums[lo];
  while (hi - lo > 1) { const m = (lo + hi) >> 1; if (nums[m] > nums[lo]) lo = m; else hi = m; }
  return nums[hi];
}
